#ifndef __CONFIG_TYPES_H__
#define __CONFIG_TYPES_H__

/* Hand-written for Apple platforms (arm64 / x86_64) in place of the one
   autoconf generates. See Vendor/README.md. */

typedef signed short ogg_int16_t;
typedef unsigned short ogg_uint16_t;
typedef signed int ogg_int32_t;
typedef unsigned int ogg_uint32_t;
typedef signed long long ogg_int64_t;
typedef unsigned long long ogg_uint64_t;
typedef signed long long ogg_int128_t;
typedef unsigned long long ogg_uint128_t;

#endif
